t[95140]={nt={de="Für Untote und Tauren. Weißsteineichenholz droppt hier von Goblin-Holzschnitzern. Weitere Teile: Verzauberter Silberbarren (Burg Shadowfang), Geläuterter Kor-Edelstein (Blackfathom-Tiefe).",en="For undead and tauren. Whitestone Oak Lumber drops from Goblin Woodcarvers here. Other parts: Enchanted Silver Ingot (Shadowfang Keep), Purified Kor Gem (Blackfathom Deeps)."},o={de="Verwendet die Mondsilberklinge, um Feuerauge den Alten im Silberwald zu vernichten."},wn={de="Questreihe mit einem Schritt in den Todesminen.",en="Chain quest with a step in The Deadmines."}}
t[95189]={nt={de="Das Wappen kann an mehreren Stellen im Dungeon erscheinen: in oberen Turmetagen, in Neben- oder Gruftkammern beim Baron und im Bereich um Bjork.",en="The Crest can appear in one of several places in the dungeon: upper tower floors, side or crypt rooms near the Baron and the area around Bjork."},o={de="Bringt das Wappen von Lordaeron zu Lady Dena Kennedy in Stormwind."}}
t[95195]={o={de="Sammelt 10 blutverschmierte Insignien und bringt sie zu General Marcus Jonathan in Stormwind."}}
