t[96337]={nt={de="Der Dokumentenkasten bringt beim Händler 25 Gold und startet „State Secrets“, das es für Horde, Allianz und Steamwheedle-Kartell gibt.",en="The Document Box sells for 25 gold and starts State Secrets, which has a Horde, an Alliance and a Steamwheedle Cartel version."},wn={de="Töte den Verhörer nicht vor dem letzten Boss, sonst bekommst du diese Quest nicht.",en="Do not kill The Questioner before the last boss, or you cannot get this quest."}}
